<?php
if (!defined('ABSPATH')) define('ABSPATH', __DIR__ . '/');
require_once dirname(__DIR__) . '/src/Services/DailyExecutionExceptionService.php';
use RoutesPro\Services\DailyExecutionExceptionService;
$assert = function($ok,$label){ if(!$ok){ fwrite(STDERR,"FAIL {$label}\n"); exit(1);} echo "PASS {$label}\n"; };
$base=['route_id'=>10,'stop_id'=>100,'location_id'=>1,'project_id'=>5,'client_id'=>2,'location_name'=>'Loja A','route_status'=>'planned'];
$completed=DailyExecutionExceptionService::classifyRecord($base+['stop_status'=>'done','submission_id'=>77,'submission_status'=>'submitted'],'2026-10-02','2026-10-02');
$assert(($completed['state']??'')==='completed' && !empty($completed['resolved']) && empty($completed['is_exception']),'completed_consistent');
$missingReport=DailyExecutionExceptionService::classifyRecord($base+['stop_status'=>'done','submission_id'=>0],'2026-10-02','2026-10-02');
$assert(($missingReport['state']??'')==='completed_without_report' && !empty($missingReport['is_exception']),'completed_without_report_detected');
$reportMismatch=DailyExecutionExceptionService::classifyRecord($base+['stop_status'=>'pending','submission_id'=>78,'submission_status'=>'approved'],'2026-10-02','2026-10-02');
$assert(($reportMismatch['state']??'')==='report_without_completion' && ($reportMismatch['severity']??'')==='critical','report_without_completion_detected');
$justified=DailyExecutionExceptionService::classifyRecord($base+['stop_status'=>'failed','fail_reason'=>'Loja encerrada','submission_id'=>0],'2026-10-02','2026-10-02');
$assert(($justified['state']??'')==='justified' && !empty($justified['resolved']) && empty($justified['is_exception']),'justified_nonvisit_terminal');
$failedNoReason=DailyExecutionExceptionService::classifyRecord($base+['stop_status'=>'failed','fail_reason'=>'','submission_id'=>0],'2026-10-02','2026-10-02');
$assert(($failedNoReason['state']??'')==='failed_without_reason' && ($failedNoReason['severity']??'')==='critical','failed_without_reason_detected');
$leftOpen=DailyExecutionExceptionService::classifyRecord($base+['stop_status'=>'in_progress','submission_id'=>0],'2026-10-01','2026-10-02');
$assert(($leftOpen['state']??'')==='visit_left_open' && !empty($leftOpen['is_exception']),'left_open_detected');
$pendingToday=DailyExecutionExceptionService::classifyRecord($base+['stop_status'=>'pending','submission_id'=>0],'2026-10-02','2026-10-02');
$assert(($pendingToday['state']??'')==='pending' && empty($pendingToday['is_exception']),'pending_today_not_false_exception');
$future=DailyExecutionExceptionService::classifyRecord($base+['stop_status'=>'pending','submission_id'=>0],'2026-10-03','2026-10-02');
$assert(($future['state']??'')==='planned' && empty($future['is_exception']),'future_planned_not_exception');
echo "DAILY EXECUTION EXCEPTION CONTROL 9BP RUNTIME OK canonical_state read_only mobile_alerts\n";
